import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, SRGBColorSpace } = ctx.THREE;

  const group = new Group();
  group.userData.handlers = {};

  const geometry = new PlaneGeometry(1.28, 0.8);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  let loadedTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((texture) => {
        loadedTexture = texture;
        texture.colorSpace = SRGBColorSpace;
        material.map = texture;
        material.needsUpdate = true;
      })
      .catch(() => {});
  }

  group.userData.cleanup = () => {
    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }
    material.dispose();
    geometry.dispose();
  };

  return group;
}
